import { get } from '@helpers/httpClient';

const mapEquipSuggest = (data: any) => ({
  name: data.name,
  text: data.name,
  weight: +data.weight,
  value: +data.value,
  photo: data.photo,
});

export async function getEquipSuggest(term: string) {
  const data = await get('/ajax/hiking/equip_acomp.php', { term });

  return data.map(mapEquipSuggest);
}
